#include "fedspatial/gpu_context.hpp"
#include <cuda_runtime.h>
#include <chrono>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <random>
#include <set>
#include <sstream>
using namespace fedspatial; namespace fs=std::filesystem;
struct Sc{int id,nu2;double nu,beta,alpha,delta;};
static std::vector<Sc> scenarios(){return {{0,1,.5,.033,1,.25},{1,1,.5,.1,1,.25},{2,1,.5,.234,1,.25},{3,3,1.5,.037,1,.25},{4,3,1.5,.11,1,.25},{5,3,1.5,.256,1,.25},{6,5,2.5,.038,1,.25},{7,5,2.5,.113,1,.25},{8,5,2.5,.264,1,.25}};}
static double cv(double d,const Sc&s){double u=(s.nu2==1?d:std::sqrt((double)s.nu2)*d)/s.beta;if(s.nu2==1)return std::exp(-u);if(s.nu2==3)return(1+u)*std::exp(-u);return(1+u+u*u/3)*std::exp(-u);}
static std::vector<double> sample_gp(GpuContext&c,const Matrix&xy,const Sc&s,std::mt19937_64&r){int n=xy.rows;std::vector<double>A(n*n),u(n);std::normal_distribution<double>N(0,1);for(int i=0;i<n;i++){u[i]=N(r);for(int j=0;j<n;j++){double dx=xy(i,0)-xy(j,0),dy=xy(i,1)-xy(j,1);A[i+n*j]=cv(std::sqrt(dx*dx+dy*dy),s)+(i==j?4:0);}}double *dA,*du,*work;int *info,wk=0;cudaMalloc(&dA,A.size()*sizeof(double));cudaMalloc(&du,u.size()*sizeof(double));cudaMalloc(&info,sizeof(int));cudaMemcpy(dA,A.data(),A.size()*sizeof(double),cudaMemcpyHostToDevice);cudaMemcpy(du,u.data(),u.size()*sizeof(double),cudaMemcpyHostToDevice);cusolverDnDpotrf_bufferSize(c.cusolver(),CUBLAS_FILL_MODE_LOWER,n,dA,n,&wk);cudaMalloc(&work,wk*sizeof(double));cusolverDnDpotrf(c.cusolver(),CUBLAS_FILL_MODE_LOWER,n,dA,n,work,wk,info);cudaDeviceSynchronize();cublasDtrmv(c.cublas(),CUBLAS_FILL_MODE_LOWER,CUBLAS_OP_N,CUBLAS_DIAG_NON_UNIT,n,dA,n,du,1);cudaMemcpy(u.data(),du,u.size()*sizeof(double),cudaMemcpyDeviceToHost);cudaFree(dA);cudaFree(du);cudaFree(work);cudaFree(info);return u;}
static bool good(const GlobalParameters&p){for(int i=0;i<5;i++)if(!std::isfinite(p.gamma(i,0)))return false;return p.delta>0&&p.alpha>0&&p.range>0&&std::isfinite(p.delta)&&std::isfinite(p.alpha)&&std::isfinite(p.range);}
static std::set<std::string> completed(const fs::path&path){std::set<std::string>out;std::ifstream in(path);std::string line;if(!in)return out;std::getline(in,line);while(std::getline(in,line)){std::stringstream q(line);std::string a,b,m;std::getline(q,a,',');std::getline(q,b,',');std::getline(q,m,',');if(!a.empty()&&!b.empty()&&!m.empty())out.insert(a+":"+b+":"+m);}return out;}
int main(int argc,char**argv){int rs=0,re=99,ss=0,se=8,device=0,modulus=1,remainder=0;bool profile=false;std::string method_filter;fs::path out="results/figure1_cpp_gpu_faithful/production",resume;for(int i=1;i<argc;i++){std::string a=argv[i];if(a=="--profile"){profile=true;continue;}if(i+1>=argc)throw std::runtime_error("missing value for "+a);if(a=="--rep-start")rs=std::stoi(argv[++i]);else if(a=="--rep-end")re=std::stoi(argv[++i]);else if(a=="--scenario-start")ss=std::stoi(argv[++i]);else if(a=="--scenario-end")se=std::stoi(argv[++i]);else if(a=="--output-dir")out=argv[++i];else if(a=="--resume-file")resume=argv[++i];else if(a=="--device")device=std::stoi(argv[++i]);else if(a=="--case-modulus")modulus=std::stoi(argv[++i]);else if(a=="--case-remainder")remainder=std::stoi(argv[++i]);else if(a=="--methods")method_filter=argv[++i];}
  if(modulus<1||remainder<0||remainder>=modulus||(method_filter!=""&&method_filter!="P"&&method_filter!="IND"))throw std::runtime_error("invalid production partition or method filter");std::vector<std::string> methods=method_filter=="P"?std::vector<std::string>{"P"}:method_filter=="IND"?std::vector<std::string>{"IND"}:std::vector<std::string>{"IND","P"};fs::create_directories(out);fs::path ep=out/"figure1_estimates.csv";std::set<std::string>done=completed(ep);if(!resume.empty()){auto prior=completed(resume);done.insert(prior.begin(),prior.end());}std::ofstream csv(ep,std::ios::app),fail(out/"figure1_failures.csv",std::ios::app),prog(out/"figure1_progress.csv",std::ios::app);if(!fs::exists(ep)||fs::file_size(ep)==0)csv<<"scenario_id,replication,method,seed,nu,beta,true_delta,true_alpha,true_beta,estimated_gamma0,estimated_gamma1,estimated_gamma2,estimated_gamma3,estimated_gamma4,estimated_delta,estimated_alpha,estimated_beta,iterations_completed,status,runtime_seconds\n";GpuContext c(device);double gt[5]={-1,2,3,-2,1};int count=done.size();auto all=scenarios();for(int si=ss;si<=se;si++)for(int rep=rs;rep<=re;rep++){if((si*100+rep)%modulus!=remainder)continue;for(const std::string&method:methods){Sc s=all[si];std::string key=std::to_string(s.id)+":"+std::to_string(rep)+":"+method;if(done.count(key))continue;try{std::mt19937_64 rng(1+rep);Matrix xy(1000,2),X(1000,5),z(1000,1);std::uniform_real_distribution<double>U(0,1);std::normal_distribution<double>N(0,1);for(int i=0;i<1000;i++){xy(i,0)=U(rng);xy(i,1)=U(rng);for(int j=0;j<5;j++)X(i,j)=N(rng);}auto wgp=sample_gp(c,xy,s,rng);for(int i=0;i<1000;i++){double v=0;for(int j=0;j<5;j++)v+=X(i,j)*gt[j];z(i,0)=v+wgp[i];}std::vector<WorkerInput>w;for(int k=0;k<10;k++){WorkerInput a{Matrix(100,2),Matrix(100,1),Matrix(100,5)};for(int i=0;i<100;i++){int g=100*k+i;for(int j=0;j<2;j++)a.sites(i,j)=xy(g,j);a.z(i,0)=z(g,0);for(int j=0;j<5;j++)a.x(i,j)=X(g,j);}w.push_back(std::move(a));}Matrix knots(100,2);for(int j=0;j<10;j++)for(int i=0;i<10;i++){knots(j*10+i,0)=(i+.5)/10.;knots(j*10+i,1)=(j+.5)/10.;}GlobalParameters p{Matrix(5,1),Matrix(100,1),Matrix(100,100),s.delta,s.alpha,s.beta};p.nu2=s.nu2;for(int i=0;i<5;i++)p.gamma(i,0)=gt[i];auto t=std::chrono::steady_clock::now();for(int it=0;it<50;it++)p=method=="P"?run_p_synchronous_round(c,w,knots,p).parameters:run_ind_synchronous_round(c,w,p).parameters;if(!good(p))throw std::runtime_error("invalid estimate");double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count();csv<<s.id<<','<<rep<<','<<method<<','<<(1+rep)<<','<<s.nu<<','<<s.beta<<','<<s.delta<<','<<s.alpha<<','<<s.beta;for(int i=0;i<5;i++)csv<<','<<p.gamma(i,0);csv<<','<<p.delta<<','<<p.alpha<<','<<p.range<<",50,OK,"<<sec<<'\n';csv.flush();prog<<++count<<","<<s.id<<","<<rep<<","<<method<<",OK\n";prog.flush();}catch(const std::exception&e){fail<<s.id<<','<<rep<<','<<method<<','<<(1+rep)<<",50,"<<e.what()<<'\n';fail.flush();}}}return 0;}
